def cadastur_igual_ao_cnpj(apps, schema_editor):
    """O CADASTUR da empresa é o número do CNPJ: os cadastros antigos passam a mostrar o CNPJ."""
    PerfilAgente = apps.get_model('contas', 'PerfilAgente')
    for perfil in PerfilAgente.objects.all():
        c = perfil.cnpj
